INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66645475', 66645475, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'DEPUTI III BIDANG PENGAWASAN PANGAN OLAHAN', 'Belanja Bahan dalam rangka Evaluasi dan Perencanaan Direktorat Standardisasi Pangan Olahan', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 12006000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Kegiatan ini mencakup kegiatan Evaluasi dan Perencanaan Direktorat Standardisasi Pangan Olahan yang meliputi kebutuhan belanja bahan penunjang berupa penyediaan konsumsi dalam pelaksanaan rapat serta kebutuhan pencetakan dokumen sebagai bagian dari kelengkapan administrasi kegiatan.', 'Paket kegiatan yang digunakan adalah Belanja Bahan dalam rangka Evaluasi dan Perencanaan Direktorat Standardisasi Pangan Olahan. Cakupan pembiayaan meliputi beberapa komponen kebutuhan bahan, yaitu biaya makan siang yang disediakan bagi seluruh peserta selama pelaksanaan rapat evaluasi dan perencanaan berlangsung, biaya snack sebagai konsumsi pendukung dalam sesi rapat, serta biaya pencetakan dokumen yang digunakan untuk memperbanyak bahan rapat, materi pembahasan, maupun dokumen hasil evaluasi dan perencanaan yang diperlukan selama kegiatan. Keseluruhan komponen belanja bahan tersebut merupakan kebutuhan operasional yang diperlukan guna mendukung kelancaran pelaksanaan rapat serta memastikan tersedianya bahan dan materi yang memadai dalam rangka Evaluasi dan Perencanaan Direktorat Standardisasi Pangan Olahan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2903045);
