INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66645468', 66645468, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'DEPUTI III BIDANG PENGAWASAN PANGAN OLAHAN', 'Paket Meeting Fullday dalam Rangka Peningkatan Kompetensi Pegawai Direktorat Standardisasi Pangan Olahan', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 14788000, 'January 2026', 'APBN - PNBP (D)', 0, 1, '1 Paket', 'Kegiatan ini mencakup kegiatan Peningkatan Kompetensi Pegawai Direktorat Standardisasi Pangan Olahan yang dilaksanakan dalam bentuk pertemuan fullday di luar kantor guna mendukung proses pembahasan dan pengembangan kompetensi pegawai', 'Paket kegiatan yang digunakan adalah Paket Meeting Fullday dalam rangka Peningkatan Kompetensi Pegawai Direktorat Standardisasi Pangan Olahan. Cakupan pembiayaan berupa biaya paket pertemuan fullday yang mencakup seluruh kebutuhan operasional penyelenggaraan pertemuan, meliputi penggunaan ruang pertemuan, fasilitas pendukung rapat, serta konsumsi peserta selama kegiatan berlangsung. Paket pertemuan fullday ini diselenggarakan guna memberikan ruang yang kondusif bagi pegawai untuk mengikuti rangkaian kegiatan peningkatan kompetensi secara penuh dan berkesinambungan dalam satu hari pelaksanaan. Keseluruhan komponen paket tersebut merupakan kebutuhan operasional yang diperlukan untuk memastikan kelancaran dan efektivitas pelaksanaan kegiatan peningkatan kompetensi Pegawai Direktorat Standardisasi Pangan Olahan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2904773);
