INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66645484', 66645484, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'DEPUTI III BIDANG PENGAWASAN PANGAN OLAHAN', 'Perjalanan Dinas Biasa dalam rangka Perkuatan Jejaring Lintas Sektor dalam Rangka Standardisasi Pangan Olahan', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 33985000, 'January 2026', 'APBN - RUPIAH MURNI (A), APBN - PNBP (D)', 0, 1, '1 Paket', 'Kegiatan ini merupakan pelaksanaan perjalanan dinas biasa dalam rangka perkuatan jejaring lintas sektor yang berkaitan dengan standardisasi pangan olahan. Perjalanan dinas dilakukan oleh petugas/pegawai yang ditugaskan untuk melaksanakan pembinaan kepada Balai di wilayah Palangkaraya, Kotawaringin Barat, Tanimbar, dan Ende, serta kegiatan koordinasi lintas sektor antarprovinsi. Melalui perjalanan dinas ini, diharapkan terbangunnya sinergi dan jejaring yang kuat antara pusat dan daerah dalam upaya penguatan standardisasi pangan olahan secara nasional.', 'Penginapan Biaya akomodasi/penginapan yang diberikan kepada petugas/pegawai selama melaksanakan perjalanan dinas di wilayah tujuan. Penginapan disediakan sesuai kebutuhan hari pelaksanaan kegiatan di masing-masing lokasi, dengan besaran biaya mengacu pada Standar Biaya Masukan (SBM) yang berlaku dan dibayarkan secara riil sesuai ketentuan yang ditetapkan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2906563);
