INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66645498', 66645498, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'DEPUTI III BIDANG PENGAWASAN PANGAN OLAHAN', 'Pelatihan dan Workshop dalam rangka Peningkatan Kompetensi Pegawai Direktorat Standardisasi Pangan Olahan', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 149192000, 'January 2026', 'APBN - PNBP (D), APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Kegiatan ini mencakup kegiatan Peningkatan Kompetensi Pegawai Direktorat Standardisasi Pangan Olahan yang dilaksanakan melalui serangkaian pelatihan dan workshop guna meningkatkan kapasitas, keahlian, dan kompetensi pegawai dalam berbagai bidang yang relevan dengan tugas dan fungsi', 'Paket kegiatan yang digunakan adalah Pelatihan dan Workshop dalam rangka Peningkatan Kompetensi Pegawai Direktorat Standardisasi Pangan Olahan. Cakupan pembiayaan meliputi beberapa program pelatihan dan workshop, yaitu 1. Pelatihan dan Sertifikasi Manajemen Risiko yang ditujukan untuk membekali pegawai dengan kemampuan identifikasi, analisis, dan mitigasi risiko dalam pelaksanaan tugas, serta Pelatihan Arsiparis Elektronik yang dirancang untuk meningkatkan kompetensi pegawai dalam pengelolaan arsip secara digital sesuai dengan ketentuan yang berlaku. 2. Workshop Negotiation and Conflict Resolution yang bertujuan untuk mengembangkan kemampuan pegawai dalam negosiasi dan penyelesaian konflik secara profesional, Workshop Strengthening Leadership and Team Management Skills to Drive Productivity yang dirancang untuk memperkuat kapasitas kepemimpinan dan manajemen tim guna mendorong peningkatan produktivitas kerja, serta Workshop Advokasi Kebijakan Publik di Bidang Pangan Olahan yang bertujuan untuk meningkatkan kemampuan pegawai dalam melakukan advokasi kebijakan publik yang berkaitan dengan standardisasi pangan olahan. Keseluruhan program pelatihan dan workshop tersebut merupakan upaya strategis yang diperlukan guna memastikan peningkatan kompetensi pegawai Direktorat Standardisasi Pangan Olahan secara komprehensif dan berkelanjutan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2907680);
