INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66645470', 66645470, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'DEPUTI III BIDANG PENGAWASAN PANGAN OLAHAN', 'Kegiatan Team Building dalam rangka Evaluasi dan Perencanaan Direktorat Standardisasi Pangan Olahan', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 36472000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Kegiatan ini mencakup kegiatan Evaluasi dan Perencanaan Direktorat Standardisasi Pangan Olahan yang dilaksanakan melalui kegiatan team building guna memperkuat soliditas, sinergi, dan kolaborasi antar pegawai dalam mendukung pelaksanaan tugas dan fungsi direktorat secara lebih efektif.', 'Paket kegiatan yang digunakan adalah Kegiatan Team Building dalam rangka Evaluasi dan Perencanaan Direktorat Standardisasi Pangan Olahan. Cakupan pembiayaan berupa biaya penyelenggaraan kegiatan team building yang mencakup seluruh kebutuhan operasional pelaksanaan kegiatan, meliputi biaya fasilitas dan venue kegiatan, perlengkapan dan peralatan yang digunakan selama sesi team building. Kegiatan team building ini dirancang sebagai wadah bagi seluruh pegawai Direktorat Standardisasi Pangan Olahan untuk mempererat hubungan antarpegawai, meningkatkan semangat kerja sama tim, serta membangun komunikasi yang lebih efektif dalam lingkungan kerja. Keseluruhan komponen biaya tersebut merupakan kebutuhan yang diperlukan guna memastikan terselenggaranya kegiatan team building secara optimal dalam rangka mendukung Evaluasi dan Perencanaan Direktorat Standardisasi Pangan Olahan.', 36472000, 'high', 'Pengadaan kegiatan team building bagi seluruh pegawai untuk mempererat hubungan, semangat kerja sama, dan komunikasi internal merupakan belanja yang manfaat langsungnya terhadap tugas pengawasan publik sulit dibuktikan dan berisiko tidak esensial. Seluruh nilai paket patut dicermati sebagai potensi pemborosan karena berorientasi pada kegiatan internal non-inti.', NULL, NULL, 3, 1, 1, 1, 1, 2908020);
