INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66645481', 66645481, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'DEPUTI III BIDANG PENGAWASAN PANGAN OLAHAN', 'Perjalanan Dinas Team Building dalam rangka Evaluasi dan Perencanaan Direktorat Standardisasi Pangan Olahan', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 50190000, 'January 2026', 'APBN - PNBP (D)', 0, 1, '1 Paket', 'Kegiatan ini mencakup kegiatan Evaluasi dan Perencanaan Direktorat Standardisasi Pangan Olahan yang dilaksanakan melalui perjalanan dinas team building di luar kota, dengan penyelenggaraan pertemuan dalam format fullday dan fullboard guna mendukung proses evaluasi, perencanaan, serta penguatan soliditas tim secara intensif dan menyeluruh.', 'Paket kegiatan yang digunakan adalah Perjalanan Dinas Team Building dalam rangka Evaluasi dan Perencanaan Direktorat Standardisasi Pangan Olahan. Cakupan pembiayaan meliputi dua komponen utama, yaitu biaya paket meeting fullday luar kota yang mencakup penggunaan ruang pertemuan, fasilitas pendukung rapat, serta konsumsi peserta selama sesi pertemuan berlangsung, serta biaya paket fullboard luar kota yang mencakup kebutuhan akomodasi penginapan beserta seluruh konsumsi peserta selama pelaksanaan kegiatan team building berlangsung. Kombinasi paket fullday dan fullboard ini dipilih guna memastikan seluruh rangkaian kegiatan team building dapat terlaksana secara intensif dan berkesinambungan, sehingga memberikan ruang yang optimal bagi pegawai untuk terlibat penuh dalam proses evaluasi capaian kinerja, perencanaan program, serta penguatan sinergi dan kolaborasi tim Direktorat Standardisasi Pangan Olahan.', 50190000, 'high', 'Pengadaan perjalanan dinas team building luar kota dengan paket meeting fullday dan fullboard berindikasi kuat tidak esensial bagi fungsi utama pengawasan/standardisasi pangan. Kegiatan evaluasi dan perencanaan pada prinsipnya dapat dilaksanakan melalui rapat kerja internal tanpa komponen team building dan akomodasi luar kota, sehingga seluruh nilai pengadaan patut dicermati sebagai potensi pemborosan.', NULL, NULL, 3, 1, 1, 1, 1, 2908289);
