INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66645502', 66645502, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'DEPUTI III BIDANG PENGAWASAN PANGAN OLAHAN', 'Perjalanan Dinas Paket Meeting Dalam dan Luar Kota dalam rangka Perkuatan Jejaring Lintas Sektor dalam Rangka Standardisasi Pangan Olahan', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 40315000, 'January 2026', 'APBN - RUPIAH MURNI (A), APBN - PNBP (D)', 0, 1, '1 Paket', 'Kegiatan ini merupakan pelaksanaan perjalanan dinas dalam bentuk paket meeting dalam dan luar kota dalam rangka perkuatan jejaring lintas sektor untuk standardisasi pangan olahan. Kegiatan dilaksanakan melalui pertemuan/rapat koordinasi yang diselenggarakan baik di dalam kota maupun di luar kota, dengan dukungan fasilitas paket meeting serta akomodasi penginapan bagi peserta yang melaksanakan kegiatan di luar kota. Kegiatan ini bertujuan untuk mempererat koordinasi dan jejaring lintas sektor antarinstansi dalam mendukung penguatan standardisasi pangan olahan secara nasional.', '1. Paket Meeting Dalam Kota Biaya paket meeting yang digunakan untuk penyelenggaraan pertemuan/rapat koordinasi lintas sektor yang dilaksanakan di dalam wilayah kota penyelenggara. Paket meeting mencakup fasilitas ruang pertemuan, konsumsi, dan perlengkapan rapat sesuai kebutuhan kegiatan, dengan besaran biaya mengacu pada Standar Biaya Masukan (SBM) yang berlaku. 2. Paket Meeting Luar Kota Biaya paket meeting yang digunakan untuk penyelenggaraan pertemuan/rapat koordinasi lintas sektor yang dilaksanakan di luar wilayah kota penyelenggara. Paket meeting mencakup fasilitas ruang pertemuan, konsumsi, dan perlengkapan rapat, dengan besaran biaya mengacu pada Standar Biaya Masukan (SBM) yang berlaku. 3. Penginapan Biaya akomodasi yang diberikan kepada peserta yang mengikuti kegiatan paket meeting luar kota, disesuaikan dengan jumlah hari pelaksanaan kegiatan. Besaran biaya mengacu pada Standar Biaya Masukan (SBM) yang berlaku dan dibayarkan secara riil sesuai ketentuan yang ditetapkan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2908714);
