INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66645471', 66645471, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'DEPUTI III BIDANG PENGAWASAN PANGAN OLAHAN', 'Biaya Perjalanan Dinas dalam rangka Forum Koordinasi Teknis Deputi Bidang Pengawasan Pangan Olahan pada Direktorat Standardisasi Pangan Olahan', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 133105000, 'January 2026', 'APBN - PNBP (D)', 0, 1, '1 Paket', 'Kegiatan ini mencakup kegiatan Forum Koordinasi Teknis Deputi Bidang Pengawasan Pangan Olahan pada Direktorat Standardisasi Pangan Olahan yang dilaksanakan melalui perjalanan dinas dengan penyelenggaraan pertemuan dalam format fullday dan fullboard, guna mendukung pelaksanaan koordinasi teknis secara intensif dan menyeluruh di luar kantor.', 'Paket kegiatan yang digunakan adalah Biaya Perjalanan Dinas dalam rangka Forum Koordinasi Teknis Deputi Bidang Pengawasan Pangan Olahan pada Direktorat Standardisasi Pangan Olahan. Cakupan pembiayaan meliputi beberapa komponen utama, yaitu biaya paket meeting fullday yang mencakup penggunaan ruang pertemuan, fasilitas pendukung rapat, serta konsumsi peserta selama sesi koordinasi teknis berlangsung dalam satu hari penuh, serta biaya paket fullboard yang mencakup kebutuhan akomodasi penginapan beserta seluruh konsumsi peserta selama pelaksanaan forum koordinasi teknis berlangsung. Selain itu, cakupan pembiayaan juga mencakup biaya penginapan yang disediakan bagi seluruh peserta guna memastikan kenyamanan dan kelancaran pelaksanaan kegiatan forum yang berlangsung lebih dari satu hari. Keseluruhan komponen biaya perjalanan dinas tersebut merupakan kebutuhan operasional yang diperlukan guna memastikan terselenggaranya Forum Koordinasi Teknis Deputi Bidang Pengawasan Pangan Olahan pada Direktorat Standardisasi Pangan Olahan secara optimal, efektif, dan berkesinambungan.', 0, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 2908964);
